using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evals;

public class ChatEvals : IAsyncLifetime
{
    private ReportingConfiguration? _reportingConfig;
    private ScenarioRun? _scenarioRun;

    public async ValueTask InitializeAsync()
    {
        var storage = new DiskBasedReportingStorage(Path.Combine("TestResults", "Evals"));
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
        };

        _reportingConfig = new ReportingConfiguration(
            evaluators,
            storage);

        _scenarioRun = await _reportingConfig.CreateScenarioRunAsync(
            "ChatScenario",
            additionalProperties: []);
    }

    public async ValueTask DisposeAsync()
    {
        if (_scenarioRun is not null)
        {
            await _scenarioRun.DisposeAsync();
        }
    }

    [Fact]
    public async Task Chat_responds_coherently_to_greeting()
    {
        // Arrange
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how are you?"),
            new(ChatRole.Assistant, "I'm doing well, thank you for asking! How can I help you today?"),
        };

        // Act
        var response = messages.Last();

        // Assert - evaluate the response quality
        var result = await _scenarioRun!.EvaluateAsync(messages, response);
        Assert.All(result, r => Assert.True(
            r.Value.Rating >= EvaluationRating.Good,
            $"Evaluator '{r.Key}' rated response as {r.Value.Rating}: {r.Value.Reason}"));
    }

    [Fact]
    public async Task Chat_responds_relevantly_to_question()
    {
        // Arrange
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?"),
            new(ChatRole.Assistant, "The capital of France is Paris."),
        };

        // Act
        var response = messages.Last();

        // Assert - evaluate the response quality
        var result = await _scenarioRun!.EvaluateAsync(messages, response);
        Assert.All(result, r => Assert.True(
            r.Value.Rating >= EvaluationRating.Good,
            $"Evaluator '{r.Key}' rated response as {r.Value.Rating}: {r.Value.Reason}"));
    }
}

